package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.io.PushbackInputStream;
import java.math.*;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.util.*;
import java.util.zip.CRC32;
import java.util.zip.DataFormatException;
import java.util.zip.Inflater;
import java.util.zip.ZipEntry;
import java.util.zip.ZipException;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveInputStream;
import org.apache.commons.compress.archivers.zip.ZipArchiveEntry;
import org.apache.commons.compress.archivers.zip.ZipArchiveInputStream;
import org.apache.commons.compress.archivers.zip.ZipException;
import org.apache.commons.compress.archivers.zip.ZipLong;
import org.apache.commons.compress.compressors.bzip2.BZip2CompressorInputStream;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.apache.commons.compress.utils.IOUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class ZipArchiveInputStream_getNextZipEntry_TriageGen1Test {

    private static final long LFH_SIG = 0x04034b50L;
    private static final long CFH_SIG = 0x02014b50L;
    private static final long AED_SIG = 0x06054b50L;

    /**
     * Helper to create a valid LFH buffer for testing.
     */
    private byte[] createLFHBuffer(String fileName, boolean hasDataDescriptor, int method, int compressedSize, int uncompressedSize, long crc) {
        int fileNameBytes = fileName.getBytes().length;
        int extraLen = 0;
        // LFH Header: Sig(4) + Ver(2) + Flags(2) + Method(2) + Time(2) + Date(2) + CRC(4) + CSize(4) + USize(4) + NameLen(2) + ExtraLen(2)
        int headerSize = 4 + 2 + 2 + 2 + 2 + 2 + 4 + 4 + 4 + 2 + 2;
        if (hasDataDescriptor) {
            headerSize = 4 + 2 + 2 + 2 + 2 + 2 + 2 + 2 + 2; // Sig + Ver + Flags + Method + Time + Date + NameLen + ExtraLen
        }

        ByteBuffer bb = ByteBuffer.allocate(headerSize + fileNameBytes + extraLen);
        bb.order(ByteOrder.LITTLE_ENDIAN);
        bb.putInt((int) LFH_SIG);
        bb.putShort((short) 0x0200); // Version 2.0, Windows
        bb.putShort((short) (hasDataDescriptor ? 0x0001 : 0x0000)); // bit 0: Data Descriptor
        bb.putShort((short) method);
        bb.putShort((short) 0); // Time
        bb.putShort((short) 0); // Date

        if (!hasDataDescriptor) {
            bb.putInt((int) crc);
            bb.putInt(compressedSize);
            bb.putInt(uncompressedSize);
        }

        bb.putShort((short) fileNameBytes);
        bb.putShort((short) extraLen);
        bb.put(fileName.getBytes());

        return bb.array();
    }

    @Test
    public void testGetNextZipEntry_Success() throws IOException {
        byte[] lfh = createLFHBuffer("test.txt", false, 0, 5, 5, 12345L);
        InputStream is = new ByteArrayInputStream(lfh);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(is);

        ZipArchiveEntry entry = zais.getNextZipEntry();
        assertNotNull(entry);
        assertEquals("test.txt", entry.getName());
        assertEquals(12345L, entry.getCrc());
    }

    @Test
    public void testGetNextZipEntry_EOF() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[0]);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(is);

        ZipArchiveEntry entry = zais.getNextZipEntry();
        assertNull(entry);
    }

    @Test
    public void testGetNextZipEntry_Closed() throws IOException {
        InputStream is = new ByteArrayInputStream(new byte[10]);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(is);
        zais.close();

        ZipArchiveEntry entry = zais.getNextZipEntry();
        assertNull(entry);
    }

    @Test
    public void testGetNextZipEntry_CentralDirectorySignature() throws IOException {
        ByteBuffer bb = ByteBuffer.allocate(4).order(ByteOrder.LITTLE_ENDIAN);
        bb.putInt((int) CFH_SIG);
        InputStream is = new ByteArrayInputStream(bb.array());
        ZipArchiveInputStream zais = new ZipArchiveInputStream(is);

        ZipArchiveEntry entry = zais.getNextZipEntry();
        assertNull(entry);
    }

    @Test
    public void testGetNextZipEntry_AEDSignature() throws IOException {
        ByteBuffer bb = ByteBuffer.allocate(4).order(ByteOrder.LITTLE_ENDIAN);
        bb.putInt((int) AED_SIG);
        InputStream is = new ByteArrayInputStream(bb.array());
        ZipArchiveInputStream zais = new ZipArchiveInputStream(is);

        ZipArchiveEntry entry = zais.getNextZipEntry();
        assertNull(entry);
    }

    @Test(expected = ZipException.class)
    public void testGetNextZipEntry_UnexpectedSignature() throws IOException {
        ByteBuffer bb = ByteBuffer.allocate(4).order(ByteOrder.LITTLE_ENDIAN);
        bb.putInt(0xDEADBEEF);
        InputStream is = new ByteArrayInputStream(bb.array());
        ZipArchiveInputStream zais = new ZipArchiveInputStream(is);

        zais.getNextZipEntry();
    }

    @Test
    public void testGetNextZipEntry_DataDescriptor() throws IOException {
        // Test path where hasDataDescriptor is true
        byte[] lfh = createLFHBuffer("data.bin", true, 0, 0, 0, 0);
        // We need to append the data descriptor after the LFH because the code reads fileName and extraData
        // But the logic in the provided code for 'hasDataDescriptor' skips 3*WORD in the LFH part
        // then reads fileName and extraData.

        // Let's simulate the stream: [LFH with flag] + [FileName] + [ExtraData] + [DataDescriptor]
        // Note: The provided code's logic for reading data descriptor is a bit tricky: 
        // it calculates 'off' but doesn't actually read the descriptor from the stream in this snippet, 
        // it just sets the flag. However, we must satisfy the 'readFully' calls.

        InputStream is = new ByteArrayInputStream(lfh);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(is);

        ZipArchiveEntry entry = zais.getNextZipEntry();
        assertNotNull(entry);
        assertTrue(entry.getGeneralPurposeBit().usesDataDescriptor());
    }

    @Test
    public void testGetNextZipEntry_SecondEntry() throws IOException {
        byte[] entry1 = createLFHBuffer("e1.txt", false, 0, 1, 1, 1);
        byte[] entry2 = createLFHBuffer("e2.txt", false, 0, 1, 1, 2);

        byte[] combined = new byte[entry1.length + entry2.length];
        System.arraycopy(entry1, 0, combined, 0, entry1.length);
        System.arraycopy(entry2, 0, combined, entry1.length, entry2.length);

        InputStream is = new ByteArrayInputStream(combined);
        ZipArchiveInputStream zais = new ZipArchiveInputStream(is);

        assertNotNull(zais.getNextZipEntry());
        assertNotNull(zais.getNextZipEntry());
        assertNull(zais.getNextZipEntry());
    }

    @Test
    public void testGetNextZipEntry_UTF8Flag() throws IOException {
        // Set bit 11 (0x800) for UTF-8
        ByteBuffer bb = ByteBuffer.allocate(100).order(ByteOrder.LITTLE_ENDIAN);
        bb.putInt((int) LFH_SIG);
        bb.putShort((short) 0x0200);
        bb.putShort((short) 0x0800); // UTF-8 flag
        bb.putShort((short) 0); // Method
        bb.putShort((short) 0); // Time
        bb.putShort((short) 0); // Date
        bb.putInt(0); // CRC
        bb.putInt(0); // CSize
        bb.putInt(0); // USize
        bb.putShort((short) 4); // NameLen
        bb.putShort((short) 0); // ExtraLen
        bb.put("test".getBytes());

        InputStream is = new ByteArrayInputStream(bb.array());
        ZipArchiveInputStream zais = new ZipArchiveInputStream(is);

        ZipArchiveEntry entry = zais.getNextZipEntry();
        assertNotNull(entry);
        assertEquals("test", entry.getName());
    }
}
